export const KNOWING_MONEY_ACTIVITIES = [
{n:1,type:"mcq",micro:"Untuk apa uang",q:"Mengapa orang menggunakan uang?",options:["Sebagai alat tukar yang diterima semua orang untuk membeli barang dan jasa","Karena setiap toko hanya mau menerima barang pecah belah sebagai pembayaran resmi","Supaya semua orang di dunia selalu memiliki jumlah barang yang persis sama banyaknya"],answer:0,explain:"Uang memudahkan pertukaran: kita bisa menjual sesuatu, menerima uang, lalu memakai uang itu membeli hal lain yang kita butuhkan.",hint:"Apa yang bisa kamu lakukan dengan uang di toko?"},
{n:2,type:"mcq",micro:"Masalah barter",q:"Sebelum ada uang, orang bertukar barang langsung (barter). Kesulitan utama barter adalah...",options:["Barang yang akan ditukar biasanya terlalu ringan sehingga tidak bisa ditimbang dengan adil","Kedua pihak harus sama-sama menginginkan barang yang dimiliki pihak lain, pada saat yang sama","Semua pemerintah melarang barter, sehingga orang yang bertukar barang selalu ditangkap petugas"],answer:1,explain:"Barter butuh 'kebetulan ganda': aku punya yang kamu mau DAN kamu punya yang aku mau. Uang menghilangkan syarat sulit ini.",hint:"Bagaimana kalau kamu punya ayam tapi penjual sepatu tidak mau ayam?"},
{n:3,type:"tf",micro:"Uang punya banyak bentuk",q:"Benar atau Salah: Uang bisa berbentuk koin logam, uang kertas, maupun saldo digital di aplikasi atau bank.",answer:true,explain:"Semua itu adalah uang selama diterima sebagai alat pembayaran. Bentuk fisiknya bisa berbeda-beda.",hint:"Apakah membayar dengan aplikasi tetap membayar dengan uang?"},
{n:4,type:"mcq",micro:"Mengenali nilai",q:"Manakah yang bernilai paling besar?",options:["Selembar uang Rp5.000","Selembar uang Rp2.000","Selembar uang Rp20.000"],answer:2,explain:"Rp20.000 lebih besar dari Rp5.000 dan Rp2.000. Membaca angka pada uang membantu kita tahu nilainya.",hint:"Bandingkan angkanya: 2.000, 20.000, 5.000."},
{n:5,type:"mcq",micro:"Menyusun jumlah",q:"Berapa cara paling sederhana membentuk Rp15.000 dari pecahan Rp5.000 dan Rp10.000?",options:["Satu lembar Rp10.000 dan satu lembar Rp5.000","Lima lembar Rp5.000 dan satu Rp10.000","Tiga lembar Rp10.000"],answer:0,explain:"Rp10.000 + Rp5.000 = Rp15.000, memakai dua lembar saja.",hint:"10.000 ditambah berapa supaya jadi 15.000?"},
{n:6,type:"mcq",micro:"Kembalian",q:"Kamu membeli jajan seharga Rp7.000 dan membayar dengan Rp10.000. Berapa kembalian yang seharusnya kamu terima?",options:["Rp17.000","Rp3.000","Rp7.000"],answer:1,explain:"Kembalian = uang yang dibayar − harga = Rp10.000 − Rp7.000 = Rp3.000.",hint:"Kurangkan harga dari uang yang kamu serahkan."},
{n:7,type:"mcq",micro:"Membaca label harga",q:"Sebuah label bertuliskan 'Rp12.500 / bungkus'. Artinya...",options:["Kamu harus membeli 12.500 bungkus","Kamu dibayar Rp12.500 untuk mengambil satu bungkus","Satu bungkus dijual seharga Rp12.500"],answer:2,explain:"Tanda '/' pada label harga berarti 'per' — harga untuk satu satuan barang tersebut.",hint:"'Per bungkus' artinya untuk setiap satu bungkus."},
{n:8,type:"order",micro:"Langkah berbelanja",q:"Urutkan langkah membeli satu barang di toko.",items:["Pilih barang yang kamu butuhkan","Lihat harganya dan pastikan uangmu cukup","Bayar di kasir","Terima barang dan kembalian, lalu periksa kembaliannya"],answer:[0,1,2,3],explain:"Pilih → cek harga vs uang → bayar → terima barang dan periksa kembalian.",hint:"Kamu perlu tahu harganya sebelum bisa membayar."},
{n:9,type:"mcq",micro:"Uang itu terbatas",q:"Kamu punya Rp10.000. Kamu ingin membeli buku Rp8.000 DAN pensil Rp5.000. Apa yang benar?",options:["Uangmu tidak cukup untuk keduanya; kamu harus memilih atau menabung dulu","Uangmu cukup untuk membeli keduanya, bahkan masih ada sisa kembalian sekitar Rp2.000 saja","Toko wajib memberi diskon otomatis supaya uangmu pas untuk membeli buku dan pensil sekaligus"],answer:0,explain:"Rp8.000 + Rp5.000 = Rp13.000, lebih dari Rp10.000. Karena uang terbatas, kita sering harus memilih.",hint:"Jumlahkan kedua harga, lalu bandingkan dengan uangmu."},
{n:10,type:"mcq",micro:"Dari mana uang berasal",q:"Cara yang umum dan sah untuk mendapatkan uang adalah...",options:["Mencetak sendiri lembaran uang di rumah dengan printer, asalkan warnanya mirip uang asli","Bekerja atau menjual barang/jasa, menerima hadiah, atau uang saku dari orang tua","Mengambil sedikit uang dari dompet orang lain secara diam-diam, selama jumlahnya kecil saja"],answer:1,explain:"Uang diperoleh dengan bekerja, berjualan, atau diberikan orang lain. Mengambil milik orang lain atau mencetak uang palsu adalah pelanggaran hukum.",hint:"Mana cara yang tidak merugikan atau melanggar hak orang lain?"},
{n:11,type:"mcq",micro:"Menyimpan uang dengan aman",q:"Tempat yang lebih aman untuk menyimpan tabungan dalam jumlah agak besar adalah...",options:["Diselipkan di antara halaman buku pelajaran yang setiap hari dibawa ke sekolah dan dipinjam teman","Dimasukkan ke saku celana yang sering dicuci dan ditinggalkan di keranjang pakaian kotor","Di rekening bank atau celengan yang disimpan orang tua"],answer:2,explain:"Uang mudah hilang atau rusak jika disimpan sembarangan. Rekening bank atau tempat aman di rumah lebih melindungi tabungan.",hint:"Mana yang paling kecil kemungkinannya hilang atau rusak?"},
{n:12,type:"tf",micro:"Uang palsu",q:"Benar atau Salah: Membuat atau menggunakan uang palsu adalah hal yang wajar dan tidak melanggar hukum selama jumlahnya kecil.",answer:false,explain:"Memalsukan uang selalu melanggar hukum dan hukumannya berat, berapa pun jumlahnya. Uang palsu merusak kepercayaan pada mata uang dan merugikan orang lain.",hint:"Apa yang terjadi kalau siapa pun boleh mencetak uang sendiri?"},
{n:13,type:"mcq",micro:"Nilai vs jumlah lembar",q:"Andi punya 10 lembar Rp1.000. Bila punya 1 lembar Rp10.000. Siapa yang punya uang lebih banyak nilainya?",options:["Keduanya sama: 10 × Rp1.000 = Rp10.000 = 1 × Rp10.000","Andi, karena lembar uangnya jauh lebih banyak jumlahnya daripada milik Bila","Bila, karena selembar uangnya bernilai lebih besar sehingga pasti lebih banyak totalnya"],answer:0,explain:"Yang penting adalah total nilai, bukan jumlah lembar. Keduanya sama-sama punya Rp10.000.",hint:"Hitung total nilai masing-masing."},
{n:14,type:"mcq",micro:"Harga total beberapa barang",q:"Kamu membeli 3 permen seharga Rp1.500 per buah. Berapa total yang harus dibayar?",options:["Rp3.000","Rp4.500","Rp1.500"],answer:1,explain:"3 × Rp1.500 = Rp4.500.",hint:"Kalikan harga satu permen dengan jumlah permen."},
{n:15,type:"mcq",micro:"Cukup atau tidak",q:"Harga tiket masuk Rp25.000. Kamu punya dua lembar Rp10.000 dan satu lembar Rp2.000. Apakah cukup?",options:["Cukup, kamu punya Rp22.000... tunggu, kurang Rp3.000","Cukup, kamu punya lebih dari Rp25.000","Tidak cukup, uangmu Rp22.000 — kurang Rp3.000"],answer:2,explain:"Rp10.000 + Rp10.000 + Rp2.000 = Rp22.000, sedangkan tiket Rp25.000. Kurang Rp3.000.",hint:"Jumlahkan uangmu dulu, lalu bandingkan dengan harga tiket."},
{n:16,type:"tf",micro:"Memeriksa kembalian",q:"Benar atau Salah: Memeriksa kembalian hanya buang waktu karena kasir tidak pernah salah menghitung.",answer:false,explain:"Kesalahan hitung bisa terjadi. Memeriksa kembalian sebelum meninggalkan kasir memudahkan memperbaikinya di tempat.",hint:"Lebih mudah membetulkan kembalian sekarang atau setelah pulang?"},
{n:17,type:"mcq",micro:"Uang digital tetap uang",q:"Saat orang tua membayar belanja dengan memindai kode QR di ponsel, yang terjadi adalah...",options:["Uang berpindah dari rekening/dompet digital mereka ke penjual, sama seperti membayar tunai","Ponsel mencetak uang baru","Belanja itu gratis"],answer:0,explain:"Pembayaran digital tetap memindahkan uang sungguhan dari pembeli ke penjual, hanya tanpa uang fisik.",hint:"Apakah saldo di aplikasi berkurang setelah membayar?"},
{n:18,type:"mcq",micro:"Harga bisa berbeda antar toko",q:"Barang yang sama bisa dijual dengan harga berbeda di dua toko. Ini berarti...",options:["Salah satu toko pasti sedang menipu pembeli, jadi toko berharga lebih murah wajib dilaporkan","Wajar; membandingkan harga sebelum membeli bisa menghemat uang","Harga barang yang sama tidak pernah boleh berbeda, jadi kedua toko pasti melanggar aturan"],answer:1,explain:"Toko menetapkan harga sendiri karena biaya dan keuntungan mereka berbeda. Membandingkan harga itu keterampilan berbelanja yang berguna.",hint:"Apa untungnya mengecek dua toko sebelum membeli?"},
{n:19,type:"mcq",micro:"Meminjam berarti mengembalikan",q:"Temanmu meminjamkan Rp5.000 untuk jajan. Yang seharusnya kamu lakukan:",options:["Meminjam uang lagi dari temanmu yang lain supaya utang dan piutangnya terlihat impas","Menganggap uang itu hadiah dan tidak perlu dikembalikan, karena temanmu pasti sudah lupa","Mengembalikan Rp5.000 itu saat kamu punya uang, sesuai kesepakatan"],answer:2,explain:"Meminjam berarti berjanji mengembalikan. Menepati janji menjaga kepercayaan.",hint:"Apa arti kata 'pinjam'?"},
{n:20,type:"open",micro:"Menjelaskan fungsi uang",q:"Dengan kata-katamu sendiri, jelaskan kepada anak yang lebih kecil mengapa uang lebih praktis daripada barter (tukar barang langsung).",explain:"Jawaban baik menyebut bahwa uang diterima semua orang sehingga menghilangkan kebutuhan 'kebetulan ganda' dalam barter.",hint:"Pikirkan kesulitan menukar telur langsung dengan sepeda.",sample:"Contoh: 'Kalau kamu punya telur dan mau sepeda, kamu harus menemukan orang yang jual sepeda DAN kebetulan mau telur — itu sulit. Dengan uang, kamu jual telur ke siapa saja yang mau, dapat uang, lalu pakai uang itu beli sepeda dari siapa saja. Uang diterima semua orang, jadi tukar-menukar jadi jauh lebih mudah.'"},
{n:21,type:"mcq",micro:"Tiga hal yang bisa dilakukan dengan uang",q:"Tiga pilihan dasar saat kamu punya uang adalah...",options:["Membelanjakannya, menabungnya, atau berbagi/memberikannya","Membakarnya, menguburnya di halaman, atau melupakannya begitu saja di dalam laci lemari","Hanya membelanjakannya sampai habis, karena tabungan dan berbagi sebenarnya tidak termasuk pilihan"],answer:0,explain:"Setiap kali menerima uang, kamu memilih: pakai sekarang (belanja), simpan untuk nanti (tabung), atau bantu orang lain (berbagi).",hint:"Sekarang, nanti, atau untuk orang lain."},
{n:22,type:"classify",micro:"Kebutuhan vs keinginan",q:"Kelompokkan tiap barang sebagai 'Kebutuhan (diperlukan untuk hidup/sekolah)' atau 'Keinginan (menyenangkan tapi bisa ditunda)'.",items:["Makanan bergizi sehari-hari","Konsol gim terbaru","Sepatu sekolah yang layak","Stiker koleksi edisi khusus"],groups:["Kebutuhan","Keinginan"],answer:{"Kebutuhan":["Makanan bergizi sehari-hari","Sepatu sekolah yang layak"],"Keinginan":["Konsol gim terbaru","Stiker koleksi edisi khusus"]},explain:"Kebutuhan adalah hal yang benar-benar diperlukan untuk hidup, kesehatan, atau sekolah. Keinginan menambah kesenangan tapi hidup tetap berjalan tanpanya.",hint:"Tanya: 'Apa yang terjadi kalau aku TIDAK punya ini?'"},
{n:23,type:"mcq",micro:"Kebutuhan vs keinginan bisa bergantung situasi",q:"Payung adalah kebutuhan atau keinginan?",options:["Selalu kebutuhan","Tergantung situasi: saat musim hujan dan harus berjalan kaki ke sekolah, ia lebih ke kebutuhan","Selalu keinginan"],answer:1,explain:"Beberapa barang berpindah kategori tergantung keadaan. Menilai konteks lebih tepat daripada label kaku.",hint:"Apakah payung sama pentingnya di musim kemarau dan musim hujan?"},
{n:24,type:"mcq",micro:"Biaya peluang",q:"Kamu punya Rp20.000 dan memilih membeli komik. 'Biaya peluang'-nya adalah...",options:["Harga komik ditambah pajak","Rp20.000 uang tunai","Hal terbaik berikutnya yang tidak jadi kamu beli/lakukan dengan uang itu, misalnya menabung untuk sepatu bola"],answer:2,explain:"Biaya peluang adalah nilai pilihan terbaik yang kamu lepaskan. Setiap keputusan uang punya biaya peluang.",hint:"Apa yang kamu korbankan dengan memilih komik?"},
{n:25,type:"mcq",micro:"Menabung berarti menunda",q:"Menabung pada dasarnya berarti...",options:["Menunda kesenangan sekarang untuk sesuatu yang lebih besar atau lebih penting nanti","Memberi uang ke bank selamanya","Kehilangan uang"],answer:0,explain:"Menabung adalah memilih 'nanti' daripada 'sekarang'. Imbalannya adalah bisa membeli hal yang lebih besar atau siap menghadapi keadaan darurat.",hint:"Uang yang ditabung hilang, atau menunggu untuk dipakai nanti?"},
{n:26,type:"mcq",micro:"Penghasilan vs pemberian",q:"Manakah yang merupakan 'penghasilan dari bekerja'?",options:["Uang ulang tahun dari nenek yang diberikan sebagai hadiah tanpa diminta bekerja apa pun","Bayaran Rp20.000 karena membantu tetangga mencuci motor","Uang Rp2.000 yang kamu temukan tergeletak di jalan saat berjalan menuju sekolah tadi pagi"],answer:1,explain:"Penghasilan dari bekerja diperoleh dengan memberikan tenaga, waktu, atau jasa. Hadiah dan uang temuan bukan hasil kerja.",hint:"Mana yang kamu dapatkan karena melakukan sesuatu untuk orang lain?"},
{n:27,type:"tf",micro:"Uang saku adalah sumber daya terbatas",q:"Benar atau Salah: Karena uang saku jumlahnya terbatas, membelanjakannya untuk satu hal berarti lebih sedikit yang tersisa untuk hal lain.",answer:true,explain:"Sumber daya terbatas memaksa pilihan (kelangkaan). Inilah alasan merencanakan pengeluaran itu penting.",hint:"Kalau kamu habiskan semua di hari Senin, apa yang tersisa untuk Jumat?"},
{n:28,type:"mcq",micro:"Melacak pengeluaran",q:"Mencatat setiap pengeluaran selama seminggu berguna untuk...",options:["Tidak ada gunanya","Membuat catatan terlihat rapi saja","Melihat ke mana uang benar-benar pergi, sering kali mengejutkan, dan menemukan tempat untuk berhemat"],answer:2,explain:"Banyak orang kaget melihat total pengeluaran kecil (jajan harian) ternyata besar bila dijumlahkan. Mencatat membuatnya terlihat.",hint:"Bagaimana kamu tahu ke mana uangmu pergi kalau tidak dicatat?"},
{n:29,type:"mcq",micro:"Pengeluaran kecil menumpuk",q:"Jajan Rp3.000 setiap hari sekolah (5 hari) selama 4 minggu berjumlah...",options:["Rp60.000","Rp12.000","Rp15.000"],answer:0,explain:"Rp3.000 × 5 hari = Rp15.000 per minggu. Rp15.000 × 4 minggu = Rp60.000. Pengeluaran kecil yang rutin menjadi besar.",hint:"Hitung per minggu dulu, lalu kalikan 4."},
{n:30,type:"order",micro:"Menabung untuk tujuan",q:"Urutkan langkah menabung untuk membeli sepeda seharga Rp600.000.",items:["Tetapkan tujuan yang jelas: sepeda Rp600.000","Tentukan berapa yang bisa kamu sisihkan tiap minggu, misalnya Rp25.000","Hitung perkiraan waktu: Rp600.000 ÷ Rp25.000 = 24 minggu","Simpan jumlah itu secara rutin dan pantau perkembangannya"],answer:[0,1,2,3],explain:"Tujuan jelas → jumlah rutin → perkiraan waktu → menabung konsisten dan memantau.",hint:"Kamu butuh target dulu sebelum bisa menghitung berapa lama."},
{n:31,type:"mcq",micro:"Dana darurat",q:"'Dana darurat' adalah tabungan yang...",options:["Dipakai khusus untuk liburan bersama teman-teman setiap akhir semester tanpa perencanaan","Disisihkan khusus untuk kejadian tak terduga seperti alat sekolah rusak atau sakit","Harus dihabiskan tiap bulan supaya tidak sempat dicuri atau hilang dari tempat penyimpanan"],answer:1,explain:"Dana darurat memberi rasa aman: saat ada pengeluaran mendadak, kamu tidak perlu berutang.",hint:"Untuk apa uang yang sengaja tidak disentuh kecuali keadaan mendesak?"},
{n:32,type:"mcq",micro:"Membandingkan harga per satuan",q:"Sabun A: Rp12.000 untuk 3 batang. Sabun B: Rp15.000 untuk 5 batang. Mana yang lebih murah per batang?",options:["Sama saja","Sabun A (Rp4.000/batang)","Sabun B (Rp3.000/batang)"],answer:2,explain:"A: Rp12.000 ÷ 3 = Rp4.000/batang. B: Rp15.000 ÷ 5 = Rp3.000/batang. B lebih hemat per batang.",hint:"Bagi harga total dengan jumlah batang untuk tiap pilihan."},
{n:33,type:"tf",micro:"Harga total lebih besar bukan berarti lebih mahal",q:"Benar atau Salah: Kemasan dengan harga total lebih tinggi selalu berarti lebih mahal per satuan daripada kemasan kecil.",answer:false,explain:"Tidak selalu. Kemasan besar sering justru lebih murah per satuan — meski hanya bermanfaat kalau kamu memang akan memakai semuanya sebelum kedaluwarsa.",hint:"Ingat perbandingan sabun A dan B."},
{n:34,type:"mcq",micro:"Diskon sederhana",q:"Baju seharga Rp80.000 diskon 25%. Berapa harga setelah diskon?",options:["Rp60.000","Rp75.000","Rp55.000"],answer:0,explain:"Diskon 25% dari Rp80.000 = Rp20.000. Harga akhir = Rp80.000 − Rp20.000 = Rp60.000.",hint:"Hitung 25% dari 80.000 dulu (seperempatnya), lalu kurangkan."},
{n:35,type:"mcq",micro:"Menunda pembelian",q:"Aturan 'tunggu 24 jam sebelum membeli barang keinginan yang mahal' membantu karena...",options:["Harga barang itu pasti akan turun besok, sehingga kamu bisa membelinya dengan harga lebih murah","Memberi waktu memeriksa apakah kamu benar-benar menginginkannya atau hanya dorongan sesaat","Toko pasti akan menyimpankan barang itu khusus untukmu selama 24 jam penuh tanpa diminta"],answer:1,explain:"Dorongan membeli sering memudar setelah beberapa jam. Menunggu memisahkan keinginan sejati dari dorongan sesaat.",hint:"Apakah semua yang sangat kamu inginkan sekarang masih kamu inginkan besok?"},
{n:36,type:"mcq",micro:"Berbagi dan berdonasi",q:"Menyisihkan sebagian kecil uang untuk berbagi (misalnya menyumbang atau membantu teman) adalah...",options:["Kewajiban yang harus dipenuhi sebesar 50% dari semua uang yang kamu terima setiap bulan","Pemborosan yang harus dihindari, karena uang hanya boleh dipakai untuk diri sendiri saja","Pilihan pribadi yang banyak orang anggap bagian penting dari mengelola uang dengan baik"],answer:2,explain:"Banyak rencana keuangan menyertakan porsi 'berbagi'. Besarnya adalah pilihan pribadi sesuai nilai dan kemampuan.",hint:"Apakah mengelola uang hanya tentang diri sendiri?"},
{n:37,type:"tf",micro:"Menabung lebih dulu",q:"Benar atau Salah: Strategi 'sisihkan tabungan lebih dulu, baru belanjakan sisanya' cenderung lebih berhasil daripada 'belanja dulu, tabung kalau ada sisa'.",answer:true,explain:"Kalau menabung menunggu 'sisa', sering tidak ada sisa. Menyisihkan di awal membuat tabungan lebih pasti.",hint:"Kapan kemungkinan besar masih ada uang untuk ditabung — di awal atau di akhir?"},
{n:38,type:"mcq",micro:"Keinginan yang menyamar jadi kebutuhan",q:"'Aku BUTUH sepatu edisi baru itu' — sering kali kata 'butuh' di sini sebenarnya berarti...",options:["Keinginan yang kuat; sepatu lama yang masih layak sudah memenuhi kebutuhan sebenarnya","Perintah dari toko","Benar-benar kebutuhan hidup"],answer:0,explain:"Kita sering memakai kata 'butuh' untuk keinginan yang kuat. Memeriksa apakah kebutuhan dasarnya sudah terpenuhi membantu berpikir jernih.",hint:"Apakah sepatu yang sekarang masih bisa dipakai ke sekolah?"},
{n:39,type:"mcq",micro:"Anggaran sederhana",q:"Uang saku mingguanmu Rp50.000. Kamu ingin: jajan Rp20.000, tabung Rp20.000, berbagi Rp5.000. Berapa sisa yang belum dialokasikan?",options:["Rp0","Rp5.000","Rp10.000"],answer:1,explain:"Rp20.000 + Rp20.000 + Rp5.000 = Rp45.000. Sisa Rp50.000 − Rp45.000 = Rp5.000 yang bisa kamu alokasikan atau simpan sebagai cadangan.",hint:"Jumlahkan semua rencana, lalu kurangkan dari total."},
{n:40,type:"open",micro:"Memutuskan dengan biaya peluang",q:"Kamu punya Rp30.000. Pilihan: (a) nonton film di bioskop bersama teman, atau (b) menambah tabungan sepeda yang kurang Rp30.000 lagi untuk lengkap. Tuliskan keputusanmu dan sebutkan biaya peluangnya.",explain:"Tidak ada satu jawaban benar; yang dinilai adalah kesadaran bahwa memilih satu berarti melepaskan yang lain, dan alasan yang masuk akal.",hint:"Sebutkan apa yang kamu dapat DAN apa yang kamu lepaskan.",sample:"Contoh: 'Aku pilih (b) melengkapi tabungan sepeda, karena sepeda akan kupakai lama dan aku sudah menabung berbulan-bulan. Biaya peluangnya adalah kehilangan kesempatan nonton bersama teman kali ini. Aku bisa mengajak mereka main sepeda gratis sebagai gantinya.' — atau pilihan (a) dengan alasan dan biaya peluang yang jelas juga bisa benar."},
{n:41,type:"mcq",micro:"Rumus dasar anggaran",q:"Hubungan dasar dalam anggaran pribadi adalah...",options:["Tabungan = Penghasilan × Pengeluaran (uang masuk dikalikan dengan uang yang dibelanjakan)","Pengeluaran selalu harus lebih besar daripada penghasilan, supaya uang cepat berputar di toko","Penghasilan = Pengeluaran + Tabungan (uang masuk dibagi ke pengeluaran dan tabungan)"],answer:2,explain:"Setiap rupiah yang masuk harus 'punya tujuan': sebagian jadi pengeluaran, sebagian jadi tabungan. Kalau pengeluaran melebihi penghasilan, kamu berutang.",hint:"Ke mana perginya semua uang yang masuk?"},
{n:42,type:"mcq",micro:"Defisit dan surplus",q:"Bulan ini penghasilan Rina Rp200.000 dan pengeluarannya Rp230.000. Kondisi ini disebut...",options:["Defisit Rp30.000 — pengeluaran melebihi pemasukan","Impas","Surplus Rp30.000"],answer:0,explain:"Defisit terjadi saat pengeluaran > penghasilan. Kekurangan Rp30.000 harus ditutup dari tabungan atau utang — tidak bisa berlanjut terus.",hint:"Pengeluaran lebih besar atau lebih kecil dari pemasukan?"},
{n:43,type:"mcq",micro:"Aturan pembagian populer",q:"Salah satu panduan sederhana membagi penghasilan adalah 50/30/20: 50% kebutuhan, 30% keinginan, 20% tabungan. Dari uang Rp100.000, berapa untuk tabungan?",options:["Rp30.000","Rp20.000","Rp50.000"],answer:1,explain:"20% dari Rp100.000 = Rp20.000 untuk tabungan. Panduan ini bisa disesuaikan dengan keadaan masing-masing.",hint:"Hitung 20% dari 100.000."},
{n:44,type:"mcq",micro:"Bunga sebagai imbalan menabung",q:"Saat kamu menyimpan uang di bank, bank kadang memberi 'bunga'. Bunga tabungan adalah...",options:["Biaya yang harus dibayar kepada bank setiap kali kamu membuka rekening tabungan yang baru","Denda yang dikenakan bank karena kamu menabung terlalu sedikit pada bulan tersebut","Tambahan uang yang diberikan bank sebagai imbalan karena kamu menyimpan uang di sana"],answer:2,explain:"Bank memakai simpananmu dan memberi sedikit imbalan (bunga). Uangmu bisa tumbuh perlahan hanya dengan disimpan.",hint:"Bunga tabungan menambah atau mengurangi saldomu?"},
{n:45,type:"mcq",micro:"Bunga sebagai biaya meminjam",q:"Saat seseorang MEMINJAM uang (misalnya dari bank atau pinjaman daring), bunga adalah...",options:["Biaya tambahan yang harus dibayar di atas jumlah pokok yang dipinjam","Potongan harga","Hadiah dari pemberi pinjaman"],answer:0,explain:"Meminjam Rp100.000 dengan bunga berarti mengembalikan lebih dari Rp100.000. Bunga adalah harga memakai uang orang lain.",hint:"Kalau menabung memberi bunga untukmu, meminjam berarti bunga untuk siapa?"},
{n:46,type:"mcq",micro:"Menghitung bunga sederhana",q:"Kamu meminjam Rp100.000 dengan bunga 10% untuk satu periode. Berapa total yang harus dikembalikan?",options:["Rp100.000","Rp110.000","Rp90.000"],answer:1,explain:"Bunga = 10% × Rp100.000 = Rp10.000. Total kembali = Rp100.000 + Rp10.000 = Rp110.000.",hint:"Hitung 10% dari pokok, lalu tambahkan ke pokok."},
{n:47,type:"mcq",micro:"Menabung teratur vs sekali besar",q:"Menabung Rp10.000 setiap minggu selama setahun (52 minggu) menghasilkan...",options:["Rp52.000","Rp120.000","Rp520.000"],answer:2,explain:"Rp10.000 × 52 = Rp520.000. Kebiasaan kecil yang konsisten menghasilkan jumlah besar seiring waktu.",hint:"Kalikan jumlah mingguan dengan 52."},
{n:48,type:"classify",micro:"Aset vs pengeluaran habis",q:"Kelompokkan tiap pembelian sebagai 'Barang tahan lama (dipakai berkali-kali)' atau 'Habis sekali pakai'.",items:["Sepeda","Pulsa untuk internet bulan ini","Sepatu sekolah","Es krim"],groups:["Barang tahan lama","Habis sekali pakai"],answer:{"Barang tahan lama":["Sepeda","Sepatu sekolah"],"Habis sekali pakai":["Pulsa untuk internet bulan ini","Es krim"]},explain:"Barang tahan lama memberi manfaat berulang selama bertahun/berbulan; barang habis pakai memberi manfaat sekali lalu selesai. Keduanya sah, tapi menyadari bedanya membantu menilai nilai uang.",hint:"Apakah kamu masih memakainya bulan depan?"},
{n:49,type:"mcq",micro:"Membandingkan penawaran",q:"Toko A: beli 2 buku tulis Rp16.000. Toko B: beli 3 buku tulis Rp21.000. Kamu butuh 6 buku. Mana yang lebih hemat?",options:["Toko B: 6 buku = Rp42.000","Sama saja","Toko A: 6 buku = Rp48.000"],answer:0,explain:"A: Rp8.000/buku → 6 × Rp8.000 = Rp48.000. B: Rp7.000/buku → 6 × Rp7.000 = Rp42.000. Toko B lebih hemat Rp6.000.",hint:"Cari harga per buku di tiap toko, lalu kalikan 6."},
{n:50,type:"mcq",micro:"Cicilan dan harga total",q:"Sebuah ponsel dijual Rp2.000.000 tunai, atau '12x Rp190.000' secara cicilan. Total cicilan adalah...",options:["Rp2.000.000, sama saja dengan harga tunai karena cicilan tidak pernah memakai tambahan biaya","Rp2.280.000 — Rp280.000 lebih mahal daripada tunai","Rp1.900.000, jadi mencicil selalu lebih murah Rp100.000 daripada membayar tunai sekaligus"],answer:1,explain:"12 × Rp190.000 = Rp2.280.000. Membayar bertahap sering lebih mahal karena mengandung bunga/biaya. Selisihnya adalah harga dari 'membayar nanti'.",hint:"Kalikan angsuran bulanan dengan jumlah bulan, lalu bandingkan dengan harga tunai."},
{n:51,type:"open",micro:"Menyusun anggaran mingguan",q:"Uang sakumu Rp60.000 per minggu. Susun anggaran yang mencakup kebutuhan (transport/jajan sehat), tabungan, dan sedikit keinginan. Tuliskan jumlah tiap pos dan pastikan totalnya tidak melebihi Rp60.000.",explain:"Anggaran yang baik: total ≤ pemasukan, ada pos tabungan yang disisihkan lebih dulu, dan pemisahan jelas antara kebutuhan dan keinginan.",hint:"Jumlahkan semua pos dan periksa tidak lebih dari Rp60.000; taruh tabungan sebagai prioritas.",sample:"Contoh: Transport Rp15.000; jajan/makan Rp18.000; tabungan Rp20.000; keinginan (jajan tambahan/mainan kecil) Rp5.000; cadangan tak terduga Rp2.000. Total = Rp60.000. Tabungan disisihkan di awal minggu, bukan menunggu sisa."},
{n:52,type:"mcq",micro:"Tujuan SMART untuk menabung",q:"Manakah tujuan menabung yang paling jelas dan bisa dipantau?",options:["Aku ingin kaya raya suatu hari nanti, entah kapan, pokoknya sebanyak-banyaknya saja","Aku ingin menabung banyak uang supaya nanti bisa membeli barang apa pun yang aku inginkan","Aku ingin menabung Rp300.000 untuk sepatu bola dalam 3 bulan, yaitu Rp25.000 per minggu"],answer:2,explain:"Tujuan yang baik menyebut jumlah, keperluan, tenggat, dan langkah rutinnya — sehingga kemajuannya bisa diukur.",hint:"Mana yang bisa kamu cek 'sudah sampai mana' setiap minggu?"},
{n:53,type:"tf",micro:"Menabung di celengan tidak bertambah sendiri",q:"Benar atau Salah: Uang di celengan tertutup akan bertambah dengan sendirinya seiring waktu, sama seperti tabungan di bank yang berbunga.",answer:false,explain:"Celengan tidak memberi imbalan apa pun; uang hanya bertambah kalau kamu memasukkan lebih banyak. Kelebihannya: uang tidak mudah terpakai. Kekurangannya: tidak tumbuh seperti rekening berbunga.",hint:"Apakah celengan memberi 'bunga'?"},
{n:54,type:"mcq",micro:"Risiko pinjaman berbunga tinggi",q:"Pinjaman daring cepat sering menawarkan uang instan tetapi dengan bunga sangat tinggi. Bahaya utamanya:",options:["Total yang harus dikembalikan bisa jauh lebih besar dari yang dipinjam, dan bila telat, bunga serta denda menumpuk cepat","Bunga yang tinggi berarti kamu akan menerima hadiah besar dari perusahaan pemberi pinjaman itu setiap saat","Tidak ada bahaya sama sekali, karena uangnya cepat cair dan bisa dipakai kapan saja kamu mau"],answer:0,explain:"Bunga tinggi membuat utang membengkak cepat. Banyak orang terjebak meminjam lagi untuk membayar utang lama.",hint:"Apa yang terjadi pada utang berbunga tinggi kalau tidak segera dilunasi?"},
{n:55,type:"mcq",micro:"Menabung untuk membeli tunai",q:"Kelebihan menabung dulu lalu membeli tunai dibanding mencicil adalah...",options:["Kamu membayar harga barang penuh ditambah bunga, sehingga barangnya terasa jauh lebih mahal","Kamu menghindari biaya bunga dan tidak punya kewajiban utang setiap bulan","Barangnya otomatis menjadi lebih mahal karena kamu menunggu lebih lama sebelum membelinya"],answer:1,explain:"Membeli tunai dari tabungan berarti tidak ada bunga dan tidak ada tekanan cicilan. Kekurangannya: harus menunggu.",hint:"Siapa yang membayar bunga saat kamu menabung lebih dulu?"},
{n:56,type:"mcq",micro:"Inflasi secara sederhana",q:"Uang jajan Rp5.000 lima tahun lalu bisa membeli lebih banyak daripada Rp5.000 sekarang. Kecenderungan harga naik seiring waktu ini disebut...",options:["Kembalian","Diskon","Inflasi"],answer:2,explain:"Inflasi adalah kenaikan harga rata-rata dari waktu ke waktu, yang membuat daya beli uang menurun bila hanya didiamkan.",hint:"Harga permen dulu dan sekarang — naik atau turun?"},
{n:57,type:"tf",micro:"Menyimpan uang tunai jangka sangat panjang",q:"Benar atau Salah: Karena inflasi, menyimpan uang tunai di bawah kasur selama bertahun-tahun berarti daya belinya perlahan berkurang.",answer:true,explain:"Uang tunai yang tidak tumbuh akan 'menyusut' nilainya dibanding harga barang yang naik. Ini alasan orang menaruh tabungan jangka panjang di tempat yang menghasilkan imbalan.",hint:"Kalau harga naik tapi uangmu tetap, apa yang terjadi pada apa yang bisa kamu beli?"},
{n:58,type:"mcq",micro:"Prioritas saat uang terbatas",q:"Uangmu terbatas bulan ini. Urutan prioritas yang masuk akal:",options:["Kebutuhan pokok dulu, lalu tabungan/kewajiban, keinginan paling akhir","Semua pengeluaran sama pentingnya, jadi belanjakan saja sesuka hati selama uangnya masih ada","Keinginan dulu, lalu kebutuhan pokok, dan tabungan atau kewajiban ditaruh paling terakhir"],answer:0,explain:"Saat sempit, dahulukan yang menjaga kehidupan berjalan (makan, transport, alat sekolah) dan kewajiban, baru sisanya untuk keinginan.",hint:"Mana yang tidak bisa ditunda tanpa masalah serius?"},
{n:59,type:"mcq",micro:"Mencatat untuk mengevaluasi",q:"Di akhir bulan kamu membandingkan anggaran rencana dengan pengeluaran nyata. Gunanya:",options:["Menghukum diri sendiri dan menyalahkan diri atas setiap rupiah yang meleset dari rencana","Melihat pos mana yang meleset, memahami sebabnya, dan memperbaiki rencana bulan depan","Tidak ada gunanya, karena uang yang sudah keluar tidak akan pernah bisa kembali lagi"],answer:1,explain:"Membandingkan rencana vs kenyataan adalah cara belajar. Anggaran adalah alat yang diperbaiki terus, bukan aturan sekali jadi.",hint:"Bagaimana anggaran bulan depan bisa lebih baik?"},
{n:60,type:"open",micro:"Menimbang menabung vs mencicil",q:"Kamu ingin sepeda Rp800.000. Pilihan A: menabung Rp50.000/minggu selama 16 minggu lalu beli tunai. Pilihan B: cicil '10x Rp90.000' dan langsung bawa pulang. Bandingkan total biaya dan sebutkan satu kelebihan tiap pilihan.",explain:"Jawaban baik menghitung selisih biaya (Rp100.000), menyebut nilai waktu/kepemilikan segera, dan memberi rekomendasi beralasan.",hint:"Hitung total tiap pilihan, lalu timbang 'hemat' vs 'punya sekarang'.",sample:"A: total Rp800.000, tanpa bunga, tapi harus menunggu ~4 bulan. B: total 10 × Rp90.000 = Rp900.000, jadi Rp100.000 lebih mahal, tetapi sepeda bisa langsung dipakai. Kelebihan A: hemat Rp100.000 dan tidak ada utang. Kelebihan B: manfaat sepeda didapat sekarang. Untuk barang yang bukan mendesak, menabung (A) biasanya lebih bijak."},
{n:61,type:"mcq",micro:"Murah belum tentu hemat",q:"Sandal Rp15.000 rusak dalam 2 minggu; sandal Rp45.000 sejenis bertahan setahun. Mana yang sebenarnya lebih hemat setahun?",options:["Tidak bisa dibandingkan, karena kedua sandal itu bentuk dan warnanya pasti berbeda satu sama lain","Yang Rp15.000, karena harga sekali belinya jauh lebih rendah sehingga pasti lebih hemat","Yang Rp45.000: yang murah butuh ~26 kali beli setahun ≈ Rp390.000, jauh lebih mahal"],answer:2,explain:"Harga per pemakaian atau per waktu sering lebih penting daripada harga di label. Barang sangat murah yang cepat rusak bisa lebih boros.",hint:"Berapa kali kamu harus membeli ulang yang murah dalam setahun?"},
{n:62,type:"mcq",micro:"Kualitas vs harga bukan garis lurus",q:"Pernyataan yang paling tepat tentang harga dan kualitas:",options:["Harga lebih tinggi kadang berarti kualitas lebih baik, tapi tidak selalu; perlu memeriksa bukti seperti ulasan dan garansi","Semakin mahal harganya, barang itu selalu pasti semakin bagus tanpa perlu diperiksa lagi bagi semua orang","Semakin murah harganya, barang itu selalu pasti semakin bagus karena penjualnya jujur"],answer:0,explain:"Harga dipengaruhi merek, kemasan, dan pemasaran, bukan hanya kualitas. Menilai dari informasi nyata lebih baik daripada menganggap 'mahal = bagus'.",hint:"Apakah barang termahal di rak selalu yang terbaik?"},
{n:63,type:"tf",micro:"Diskon pada barang yang tidak dibutuhkan",q:"Benar atau Salah: Membeli barang seharga Rp90.000 yang tidak kamu butuhkan karena 'diskon dari Rp150.000' berarti kamu menghemat Rp60.000.",answer:false,explain:"Kalau kamu tidak akan membelinya tanpa diskon, kamu tidak menghemat Rp60.000 — kamu MENGELUARKAN Rp90.000 yang tadinya bisa kamu simpan.",hint:"Uangmu bertambah atau berkurang setelah pembelian itu?"},
{n:64,type:"mcq",micro:"Tujuan iklan",q:"Tujuan utama sebuah iklan adalah...",options:["Memberi informasi netral dan lengkap termasuk kelemahan produk","Membuat kamu ingin dan membeli produk itu, dengan menonjolkan sisi baiknya","Membantumu berhemat"],answer:1,explain:"Iklan dibuat oleh penjual untuk mendorong pembelian. Ia menonjolkan kelebihan dan jarang menyebut kekurangan. Sikap kritis diperlukan.",hint:"Siapa yang membayar iklan itu, dan apa yang mereka inginkan darimu?"},
{n:65,type:"mcq",micro:"Taktik 'terbatas'",q:"'Stok tinggal 3! Promo berakhir 1 jam lagi!' Taktik ini bekerja dengan...",options:["Menurunkan harga barang secara nyata sehingga kamu benar-benar mendapat barang yang lebih murah","Memberikan fakta lengkap yang membantu kamu mengambil keputusan dengan tenang dan teliti","Menciptakan rasa terburu-buru dan takut ketinggalan sehingga kamu membeli tanpa berpikir panjang"],answer:2,explain:"Tekanan waktu dan kelangkaan buatan mengurangi pertimbangan. Mengenali taktik ini membantumu berhenti dan berpikir.",hint:"Apakah rasa panik membantumu membuat keputusan uang yang baik?"},
{n:66,type:"mcq",micro:"Terlalu bagus untuk jadi kenyataan",q:"Sebuah pesan menjanjikan 'Setor Rp100.000, dapat Rp1.000.000 dalam seminggu, dijamin!' Ini kemungkinan besar...",options:["Penipuan — imbal hasil sangat tinggi dalam waktu singkat dengan 'jaminan' hampir selalu tipuan","Program resmi dari pemerintah yang aman diikuti, sehingga uang setoran pasti kembali berlipat","Kesempatan bagus yang harus segera diambil sebelum diikuti oleh banyak orang lain lebih dulu"],answer:0,explain:"Tidak ada investasi sah yang menjamin keuntungan besar secepat itu. 'Dijamin' + 'cepat' + 'besar' adalah tanda bahaya klasik penipuan.",hint:"Kalau semudah itu menggandakan uang, mengapa mereka butuh uangmu?"},
{n:67,type:"tf",micro:"Merahasiakan data keuangan",q:"Benar atau Salah: Membagikan nomor PIN, kata sandi aplikasi uang, atau kode OTP kepada orang lain — bahkan yang mengaku petugas bank — adalah tindakan berisiko tinggi.",answer:true,explain:"Petugas bank yang sah tidak pernah meminta PIN atau OTP. Kode itu adalah kunci uangmu; membagikannya bisa berarti kehilangan seluruh saldo.",hint:"Apakah ada alasan sah bagi orang lain untuk tahu PIN-mu?"},
{n:68,type:"mcq",micro:"Pembelian impulsif dan penempatan barang",q:"Permen dan mainan kecil sering diletakkan di dekat kasir karena...",options:["Kebetulan saja","Saat mengantre, orang cenderung mengambil barang murah tanpa rencana (pembelian impulsif)","Tempat lain penuh"],answer:1,explain:"Tata letak toko dirancang mendorong pembelian tak terencana. Menyiapkan daftar belanja membantu menahannya.",hint:"Mengapa barang menarik dan murah ada tepat di jalur antre?"},
{n:69,type:"mcq",micro:"Biaya tersembunyi",q:"Sebuah 'permainan gratis' di ponsel menghasilkan uang lewat...",options:["Pemerintah yang membayar para pembuat permainan itu setiap kali ada yang mengunduhnya dari toko","Permainan itu tidak menghasilkan uang apa pun, pembuatnya hanya membuatnya karena iseng saja","Iklan dan pembelian di dalam aplikasi (item, nyawa tambahan) yang lama-lama bisa menjadi besar"],answer:2,explain:"'Gratis' di awal sering berarti biaya muncul kemudian. Menyadari model ini membantu mengontrol pengeluaran kecil yang menumpuk.",hint:"Bagaimana pembuat game gratis mendapat uang?"},
{n:70,type:"order",micro:"Memeriksa sebuah 'penawaran spesial'",q:"Urutkan langkah menilai iklan 'Diskon 70%! Hari ini saja!'.",items:["Cek harga normal barang itu di tempat lain untuk memastikan 'harga sebelum diskon' tidak digelembungkan","Tanya pada diri sendiri: apakah aku memang berencana membeli ini sebelum melihat iklannya?","Hitung harga akhir sebenarnya dan bandingkan dengan anggaranku","Putuskan tanpa terburu-buru; kalau ragu, lewati"],answer:[1,0,2,3],explain:"Mulai dari 'apakah aku butuh ini', lalu periksa keaslian diskon, hitung dampaknya ke anggaran, baru putuskan dengan tenang.",hint:"Pertanyaan terpenting bukan 'berapa diskonnya' tapi 'apakah aku memang mau beli ini'."},
{n:71,type:"mcq",micro:"Keadilan dalam pertukaran",q:"Kamu menukar 5 kartu koleksi biasa milikmu dengan 1 kartu langka milik teman kelas 3 yang belum tahu nilainya. Kamu tahu kartunya sebenarnya sangat berharga. Sikap yang adil:",options:["Beri tahu dia perkiraan nilai kartunya sebelum tukar, supaya keputusannya didasari informasi yang sama","Ambil dua kartu langka sekalian, sebab dia pasti belum tahu bahwa kamu sebenarnya memintanya","Lanjutkan saja, karena dia sendiri yang setuju dan itu bukan lagi urusan atau tanggung jawabmu"],answer:0,explain:"Pertukaran yang adil terjadi saat kedua pihak memahami nilai yang mereka berikan dan terima. Memanfaatkan ketidaktahuan orang lain tidak adil.",hint:"Apakah kedua pihak tahu sama banyak tentang apa yang ditukar?"},
{n:72,type:"mcq",micro:"Tekanan teman sebaya dan uang",q:"Teman-teman mengajak patungan Rp50.000 untuk sesuatu yang tidak kamu minati, dan uangmu untuk keperluan lain. Respons yang sehat:",options:["Ikut saja supaya tidak dianggap pelit dan tidak dijauhi, walau uangnya sebenarnya sudah ada tujuan","Menolak dengan sopan dan menjelaskan bahwa uangmu sudah dialokasikan; menawarkan cara ikut yang gratis","Meminjam uang dari teman lain untuk ikut patungan supaya tidak ada yang kecewa kepadamu"],answer:1,explain:"Keputusan uang yang baik kadang berarti mengatakan 'tidak' pada tekanan sosial. Teman yang baik menghormati batasan itu.",hint:"Apakah harga persahabatan itu Rp50.000 yang sudah punya tujuan lain?"},
{n:73,type:"tf",micro:"Utang untuk keinginan vs untuk hal produktif",q:"Benar atau Salah: Berutang untuk barang yang cepat habis dipakai sama amannya dengan berutang untuk sesuatu yang bisa menghasilkan atau menghemat uang di kemudian hari.",answer:false,explain:"Umumnya tidak sama. Utang untuk barang konsumtif meninggalkan kewajiban tanpa aset, sedangkan utang untuk alat yang membantu berpenghasilan setidaknya berpotensi 'membayar dirinya sendiri' — meski keduanya tetap perlu hati-hati.",hint:"Setelah utang lunas, apakah kamu masih punya sesuatu yang bernilai?"},
{n:74,type:"mcq",micro:"Membandingkan bukan hanya harga",q:"Saat memilih di antara dua barang serupa, faktor SELAIN harga yang layak dipertimbangkan:",options:["Tidak ada, harga satu-satunya yang penting","Hanya warna kemasan","Daya tahan, garansi, ulasan pengguna, biaya perawatan, dan kecocokan dengan kebutuhanmu"],answer:2,explain:"Nilai sebenarnya = manfaat total ÷ biaya total sepanjang pemakaian, bukan sekadar angka di label.",hint:"Apa yang memengaruhi kepuasanmu selama berbulan-bulan memakai barang itu?"},
{n:75,type:"mcq",micro:"Efek 'gratis ongkir minimal belanja'",q:"'Gratis ongkir untuk belanja minimal Rp150.000' sering membuat orang...",options:["Menambah barang yang tidak direncanakan hanya untuk mencapai Rp150.000, sehingga total pengeluaran malah lebih besar","Membatalkan seluruh pembelian karena merasa syarat minimal belanjanya terlalu tinggi untuk dipenuhi","Berbelanja tepat sesuai daftar kebutuhan, lalu pulang tanpa tambahan barang apa pun dari toko"],answer:0,explain:"Menambah Rp40.000 barang tak perlu demi 'menghemat' Rp20.000 ongkir berarti rugi Rp20.000. Hitung total, bukan hanya ongkirnya.",hint:"Bandingkan ongkir yang dihemat dengan nilai barang tambahan yang dibeli."},
{n:76,type:"mcq",micro:"Menabung sebagai kebebasan memilih",q:"Selain untuk membeli sesuatu, memiliki tabungan memberi manfaat berupa...",options:["Beban pikiran yang lebih berat, karena kamu harus terus menjaga dan memikirkan uang tabunganmu setiap saat","Kebebasan dan ketenangan: bisa menghadapi kejadian tak terduga dan menolak pilihan buruk (misalnya pinjaman berbunga tinggi)","Kewajiban untuk membelanjakannya dengan cepat supaya uang tidak lama tertahan di tabungan"],answer:1,explain:"Tabungan adalah penyangga. Orang dengan tabungan punya lebih banyak pilihan dan lebih sedikit tekanan saat masalah datang.",hint:"Siapa yang lebih tenang saat sepatu tiba-tiba jebol: yang punya tabungan atau yang tidak?"},
{n:77,type:"tf",micro:"Semua pengeluaran keinginan itu buruk",q:"Benar atau Salah: Mengelola uang dengan baik berarti tidak pernah membelanjakan uang untuk kesenangan.",answer:false,explain:"Rencana keuangan yang sehat menyertakan porsi untuk kesenangan. Tujuannya bukan pantang total, melainkan pengeluaran yang disengaja dan seimbang.",hint:"Apakah anggaran yang tidak pernah membolehkan kesenangan bisa bertahan lama?"},
{n:78,type:"mcq",micro:"Menilai peluang menghasilkan uang",q:"Seseorang menawarkan 'kerja dari rumah, gaji besar, tapi bayar dulu Rp200.000 untuk pendaftaran dan alat'. Tanda bahaya di sini:",options:["Gaji yang besar berarti pekerjaan itu pasti bagus, jadi kamu sebaiknya langsung membayar pendaftarannya","Tidak ada tanda bahaya, sebab sudah wajar membayar biaya di muka untuk mulai bekerja dari rumah","Pekerjaan sah umumnya MEMBAYAR kamu, bukan meminta kamu membayar di muka untuk 'kesempatan' — ini pola umum penipuan"],answer:2,explain:"Meminta biaya di muka untuk 'pekerjaan' bergaji besar adalah skema penipuan klasik. Uang pendaftaran hilang dan pekerjaannya tidak nyata.",hint:"Dalam pekerjaan biasa, siapa membayar siapa?"},
{n:79,type:"mcq",micro:"Nilai waktu",q:"Menghabiskan 2 jam berkeliling 5 toko untuk menghemat Rp2.000 pada sebungkus garam...",options:["Sering tidak sepadan; waktu dan tenaga itu berharga dan bisa dipakai untuk hal yang lebih bernilai","Wajib dilakukan setiap kali berbelanja, karena sedikit penghematan pasti selalu bermanfaat besar","Selalu sepadan, sebab hemat tetap hemat berapa pun waktu dan tenaga yang harus dikeluarkan"],answer:0,explain:"Berhemat itu baik, tapi usaha berhemat juga punya biaya (waktu, tenaga). Fokuskan perbandingan harga pada pembelian yang besar.",hint:"Apakah Rp2.000 sebanding dengan 2 jam waktumu?"},
{n:80,type:"open",micro:"Membongkar sebuah iklan",q:"Pilih satu iklan yang pernah kamu lihat (di TV, aplikasi, atau poster). Tuliskan: (a) apa yang dijanjikannya, (b) satu hal yang TIDAK disebutkan (kekurangan, syarat, atau biaya tambahan), dan (c) pertanyaan yang akan kamu ajukan sebelum membeli.",explain:"Jawaban baik memisahkan klaim dari bukti, mengenali informasi yang sengaja tidak ditonjolkan, dan menyiapkan pertanyaan verifikasi.",hint:"Iklan menonjolkan yang baik — apa yang mereka harap kamu tidak tanyakan?",sample:"Contoh: Iklan minuman serbuk 'bikin pintar dan berenergi'. (a) Janji: anak jadi lebih fokus dan bertenaga. (b) Tidak disebut: kandungan gulanya tinggi, dan tidak ada bukti ilmiah soal 'jadi pintar'. (c) Pertanyaan: 'Berapa gula per sajian? Apakah ada penelitian independen? Berapa harga per gelas dibanding susu biasa?'"},
{n:81,type:"mcq",micro:"Menghitung untung sederhana",q:"Kamu membuat 20 gelas es teh. Biaya bahan + es + gelas total Rp30.000. Kamu jual Rp3.000 per gelas dan semua laku. Berapa untungnya?",options:["Rp60.000","Rp30.000","Rp90.000"],answer:1,explain:"Pendapatan = 20 × Rp3.000 = Rp60.000. Untung = pendapatan − biaya = Rp60.000 − Rp30.000 = Rp30.000.",hint:"Untung = semua uang masuk − semua biaya."},
{n:82,type:"mcq",micro:"Menentukan harga jual",q:"Untuk usaha kecil, harga jual per satuan sebaiknya minimal...",options:["Di bawah biaya per satuan, supaya barang dagangan cepat laku dan stok segera habis terjual","Sama persis dengan biaya per satuan, supaya impas dan pembeli merasa harganya paling adil","Di atas biaya per satuan, agar ada untung untuk menutup risiko dan usahamu"],answer:2,explain:"Kalau harga = biaya, kamu tidak untung. Kalau harga < biaya, kamu rugi tiap penjualan. Harga harus menutup biaya DAN memberi margin.",hint:"Apa gunanya berjualan kalau tiap gelas membuatmu rugi?"},
{n:83,type:"mcq",micro:"Risiko barang tak laku",q:"Kamu belanja bahan untuk 50 kue, tapi hanya 30 yang laku dan sisanya basi. Pelajaran pengelolaan risikonya:",options:["Mulai dari jumlah kecil sesuai permintaan yang sudah pasti, lalu tambah bertahap setelah tahu berapa yang benar-benar laku","Turunkan harga sampai rugi besar supaya semua kue habis terjual dalam satu hari saja","Selalu buat sebanyak mungkin kue, karena stok yang banyak pasti akan laku pada akhirnya bagi semua orang"],answer:0,explain:"Memproduksi berlebih mengunci uang di barang yang mungkin tidak terjual. Uji pasar dengan jumlah kecil dulu.",hint:"Bagaimana kamu tahu berapa yang akan laku sebelum mencoba?"},
{n:84,type:"order",micro:"Merencanakan usaha kecil",q:"Urutkan langkah merencanakan usaha menjual gelang buatan di bazar sekolah.",items:["Perkirakan berapa orang yang mungkin membeli dan pada harga berapa","Hitung biaya bahan per gelang dan total modal yang dibutuhkan","Tetapkan harga jual di atas biaya per gelang","Buat sedikit dulu untuk bazar pertama, catat penjualan, lalu sesuaikan"],answer:[0,1,2,3],explain:"Pahami permintaan → hitung biaya → tetapkan harga → uji kecil dan perbaiki. Ini siklus dasar wirausaha.",hint:"Kamu perlu tahu calon pembeli dan biaya sebelum menetapkan harga."},
{n:85,type:"mcq",micro:"Menilai sebuah 'deal' bundel",q:"Bundel A: 1 buku + 1 pena + 1 penggaris seharga Rp25.000. Kalau dibeli terpisah: buku Rp15.000, pena Rp4.000, penggaris Rp3.000. Apakah bundel ini hemat?",options:["Ya, hemat Rp25.000","Ya, tapi hanya Rp3.000 dan hanya jika kamu butuh KETIGA barang itu","Tidak pernah hemat"],answer:1,explain:"Terpisah = Rp22.000. Bundel Rp25.000 justru Rp3.000 LEBIH MAHAL. Bundel hanya 'hemat' bila harganya di bawah total terpisah DAN kamu memakai semua isinya.",hint:"Jumlahkan harga terpisah dan bandingkan dengan harga bundel."},
{n:86,type:"mcq",micro:"Membagi penghasilan usaha",q:"Untungmu berjualan bulan ini Rp120.000. Pembagian yang bijak untuk pelajar wirausaha:",options:["Pinjamkan semua keuntungannya ke teman tanpa catatan, supaya persahabatan kalian semakin erat","Habiskan semuanya untuk merayakan keberhasilan, karena keuntungan memang untuk dinikmati saat ini juga","Sisihkan sebagian sebagai modal putar untuk stok berikutnya, sebagian ditabung, sebagian boleh dinikmati"],answer:2,explain:"Menyisihkan modal putar menjaga usaha tetap berjalan; menabung membangun cadangan; menikmati sebagian menjaga semangat. Menghabiskan semua menghentikan usaha.",hint:"Kalau semua untung dipakai, dari mana modal stok berikutnya?"},
{n:87,type:"tf",micro:"Waktu dan tenaga adalah biaya",q:"Benar atau Salah: Saat menilai apakah sebuah usaha kecil sepadan, cukup menghitung biaya bahan saja; waktu dan tenaga yang kamu curahkan tidak perlu diperhitungkan.",answer:false,explain:"Waktu dan tenaga juga biaya. Jika 10 jam kerja hanya menghasilkan untung Rp10.000, mungkin ada cara lain yang lebih berharga untuk waktu itu.",hint:"Apakah untung Rp5.000 sepadan dengan seharian penuh bekerja?"},
{n:88,type:"mcq",micro:"Menabung dengan bunga majemuk (gagasan)",q:"Kamu menabung Rp100.000 di rekening berbunga 10% per tahun, dan bunganya ikut ditabung. Setelah 2 tahun (bunga majemuk), saldonya sekitar...",options:["Rp121.000","Rp110.000","Rp120.000"],answer:0,explain:"Tahun 1: Rp100.000 → Rp110.000. Tahun 2: bunga 10% dihitung dari Rp110.000 = Rp11.000 → Rp121.000. Bunga menghasilkan bunga lagi.",hint:"Tahun kedua, bunga dihitung dari saldo baru, bukan dari Rp100.000."},
{n:89,type:"mcq",micro:"Keputusan di bawah tekanan",q:"Di toko, temanmu mendesak 'Ayo beli sekarang, nanti kehabisan!' padahal barang itu tidak ada di rencanamu. Langkah terbaik:",options:["Langsung beli agar tidak menyesal nanti, karena barang yang kehabisan tidak mungkin ada lagi bagi semua orang","Tarik napas, ingat anggaran dan tujuanmu, dan katakan kamu akan memikirkannya dulu — kelangkaan mendesak sering dilebih-lebihkan","Pinjam uang temanmu itu untuk membeli barangnya, lalu kembalikan setelah uang sakumu cukup"],answer:1,explain:"Keputusan uang yang baik jarang perlu diambil dalam hitungan detik. Memberi jeda memisahkan dorongan dari kebutuhan nyata.",hint:"Apa yang biasanya kamu rasakan sehari setelah membeli karena panik?"},
{n:90,type:"tf",micro:"Rencana keuangan bersifat pribadi",q:"Benar atau Salah: Cara terbaik membagi uang bisa berbeda antar orang, tergantung penghasilan, kebutuhan, tanggungan, dan tujuannya.",answer:true,explain:"Panduan seperti 50/30/20 hanyalah titik awal. Keadaan tiap orang berbeda, jadi rencana perlu disesuaikan, bukan disalin mentah.",hint:"Apakah anak dengan uang saku Rp20.000 dan Rp200.000 punya rencana yang sama?"},
{n:91,type:"mcq",micro:"Menghitung berapa lama mencapai tujuan",q:"Kamu ingin mengumpulkan Rp450.000 untuk kursus. Kamu bisa menabung Rp30.000/minggu dan sudah punya Rp90.000. Berapa minggu lagi yang dibutuhkan?",options:["18 minggu","15 minggu","12 minggu"],answer:2,explain:"Sisa yang dibutuhkan = Rp450.000 − Rp90.000 = Rp360.000. Rp360.000 ÷ Rp30.000 = 12 minggu.",hint:"Kurangi tabungan yang sudah ada dulu, lalu bagi dengan tabungan per minggu."},
{n:92,type:"mcq",micro:"Menolak 'menggandakan uang' cepat",q:"Kakak kelas menawarkan: 'Titip Rp100.000, minggu depan jadi Rp150.000, aku putar di bisnis rahasia.' Respons paling aman:",options:["Menolak: keuntungan 50% dalam seminggu tidak realistis dan 'bisnis rahasia' tanpa bukti adalah tanda penipuan; uangmu bisa hilang total","Titipkan setengahnya saja, supaya kalau rugi kamu tidak kehilangan seluruh uang yang kamu punya, sebagaimana biasanya","Titipkan seluruhnya, karena keuntungannya besar dan kakak kelas pasti tidak mungkin berbohong"],answer:0,explain:"Janji imbal hasil tinggi, cepat, dan tanpa transparansi adalah ciri skema penipuan. Menjaga uang tetap padamu jauh lebih aman.",hint:"Kalau bisnisnya benar-benar menghasilkan 50% seminggu, kenapa dia butuh Rp100.000-mu?"},
{n:93,type:"mcq",micro:"Membedakan menabung dan berinvestasi",q:"Perbedaan mendasar antara menabung dan berinvestasi adalah...",options:["Tidak ada bedanya","Menabung menekankan keamanan dan uang mudah diambil (imbalan kecil); berinvestasi menerima risiko naik-turun demi potensi pertumbuhan lebih besar dalam jangka panjang","Berinvestasi selalu bebas risiko"],answer:1,explain:"Tabungan cocok untuk dana darurat dan tujuan dekat. Investasi cocok untuk tujuan jangka panjang, dengan kesadaran bahwa nilainya bisa turun sebelum naik.",hint:"Mana yang nilainya bisa berkurang sebelum bertambah?"},
{n:94,type:"open",micro:"Merencanakan pembelian besar dengan anggaran",q:"Kamu ingin membeli tablet untuk belajar seharga Rp2.400.000. Uang sakumu Rp80.000/minggu; kamu juga bisa mendapat Rp100.000/bulan dari membantu usaha orang tua. Buat rencana: berapa yang disisihkan tiap minggu/bulan, berapa lama sampai tercapai, dan apa yang kamu korbankan.",explain:"Rencana baik menyebut jumlah sisihan realistis, menghitung durasi, menyatakan biaya peluang, dan menawarkan satu cara mempercepat.",hint:"Total tabungan bulanan → bagi harga → nyatakan durasi → sebut apa yang kamu lepaskan.",sample:"Contoh: Sisihkan Rp40.000/minggu dari uang saku (Rp160.000/bulan) + Rp100.000/bulan dari membantu usaha = Rp260.000/bulan. Rp2.400.000 ÷ Rp260.000 ≈ 9,2 bulan, jadi sekitar 10 bulan. Yang dikorbankan: separuh jajan mingguan dan sebagian waktu luang untuk membantu usaha. Alternatif mempercepat: cari pekerjaan kecil tambahan, atau pilih tablet lebih murah Rp1.800.000 sehingga tercapai dalam ~7 bulan."},
{n:95,type:"mcq",micro:"Mengevaluasi setelah membeli",q:"Sebulan setelah membeli sesuatu yang mahal, pertanyaan refleksi yang berguna:",options:["Berapa harga barang itu sekarang di toko lain, dan apakah ada teman yang membeli barang sejenis? bagi semua orang pada akhirnya","Tidak ada pertanyaan yang perlu diajukan, sebab uangnya sudah keluar dan tidak bisa kembali lagi","Apakah aku memakainya seperti yang kubayangkan? Apakah pembelian ini masih terasa sepadan? Apa yang bisa kupelajari untuk pembelian besar berikutnya?"],answer:2,explain:"Meninjau pembelian besar membangun penilaian yang lebih baik dari waktu ke waktu — mana yang benar-benar memberi nilai, mana yang menyesal.",hint:"Bagaimana pembelian besar berikutnya bisa lebih tepat?"},
{n:96,type:"tf",micro:"Berbagi tidak harus besar untuk berarti",q:"Benar atau Salah: Menyisihkan jumlah kecil secara rutin untuk membantu orang lain bisa berdampak nyata dari waktu ke waktu, sama seperti menabung kecil menjadi besar.",answer:true,explain:"Kebiasaan konsisten — menabung maupun berbagi — memberi hasil yang menumpuk. Nilainya ada pada keteraturannya, bukan hanya besarnya.",hint:"Kalau menabung Rp5.000/minggu jadi besar setahun, bagaimana dengan berbagi Rp5.000/minggu?"},
{n:97,type:"mcq",micro:"Prioritas antar tujuan tabungan",q:"Kamu punya tiga tujuan: dana darurat (belum ada), sepatu bola (keinginan), kado ulang tahun ibu bulan depan (kebutuhan sosial, tenggat dekat). Urutan menabung yang masuk akal:",options:["Mulai dana darurat kecil DAN kado ibu (tenggat dekat) lebih dulu, sepatu bola setelahnya","Abaikan semua tujuan itu dan tabung nanti saja, tanpa perlu menetapkan jumlah dan waktunya sekarang","Sepatu bola dulu karena itulah yang paling kamu inginkan, sedangkan dana darurat bisa menunggu lebih lama"],answer:0,explain:"Prioritas mempertimbangkan urgensi (tenggat kado), keamanan (dana darurat), lalu keinginan. Beberapa tujuan bisa jalan bersamaan dengan porsi berbeda.",hint:"Mana yang punya tenggat, dan mana yang melindungimu dari masalah?"},
{n:98,type:"mcq",micro:"Uang dan nilai hidup",q:"Pandangan paling sehat tentang uang adalah...",options:["Uang adalah tujuan akhir hidup, sehingga semakin banyak uang yang dimiliki, semakin bahagia pula seseorang","Uang adalah alat untuk mencapai hal yang kamu anggap penting — keamanan, kesempatan belajar, membantu keluarga — bukan tujuan itu sendiri","Uang tidak penting sama sekali, sehingga sebaiknya kita tidak perlu memikirkan atau mengelolanya dengan serius setiap saat"],answer:1,explain:"Mengelola uang dengan baik memberi kebebasan dan pilihan untuk hidup sesuai nilaimu. Uang melayani tujuan, bukan sebaliknya.",hint:"Untuk apa sebenarnya kamu menginginkan uang?"},
{n:99,type:"mcq",micro:"Kebiasaan yang paling berpengaruh",q:"Dari semua kebiasaan keuangan, yang paling konsisten membantu orang dari waktu ke waktu adalah...",options:["Sering berganti dompet","Menebak angka lotre","Membelanjakan lebih sedikit dari yang dihasilkan, dan menyisihkan selisihnya secara teratur"],answer:2,explain:"'Pengeluaran < penghasilan, dan tabung selisihnya' adalah inti dari hampir semua nasihat keuangan yang baik, pada tingkat penghasilan berapa pun.",hint:"Apa satu kalimat yang mendasari semua rencana keuangan sehat?"},
{n:100,type:"open",micro:"Kapstone: rencana uang pribadi tiga bulan",q:"Buat rencana keuangan pribadi untuk tiga bulan ke depan. Sertakan: (1) perkiraan total pemasukan (uang saku + lainnya), (2) pembagian ke kebutuhan / keinginan / tabungan / berbagi dengan angka, (3) satu tujuan tabungan spesifik dengan jumlah dan tenggat, (4) satu 'aturan pribadi' untuk menahan pembelian impulsif, dan (5) bagaimana kamu akan mengecek di akhir tiap bulan apakah rencana berjalan.",explain:"Kapstone menggabungkan seluruh keterampilan: menghitung pemasukan, menganggarkan dengan proporsi, menetapkan tujuan terukur, membuat aturan menahan impuls, dan menjadwalkan evaluasi berkala.",hint:"Kerjakan kelima bagian dengan angka nyata; pastikan total pengeluaran + tabungan tidak melebihi pemasukan.",sample:"Contoh: (1) Pemasukan: uang saku Rp60.000/minggu ≈ Rp240.000/bulan + bantu paman Rp80.000/bulan = Rp320.000/bulan; 3 bulan ≈ Rp960.000. (2) Per bulan: kebutuhan (transport, makan) Rp150.000; keinginan Rp40.000; tabungan Rp100.000; berbagi Rp15.000; cadangan Rp15.000. (3) Tujuan: sepatu lari Rp300.000 dalam 3 bulan (Rp100.000/bulan). (4) Aturan pribadi: 'Untuk barang keinginan di atas Rp25.000, tunggu 2 hari; kalau masih mau dan anggaran keinginan cukup, baru beli.' (5) Setiap akhir bulan: bandingkan catatan pengeluaran nyata dengan rencana, tandai pos yang meleset, cari sebabnya, sesuaikan bulan berikutnya."},
];
